import os
import requests

def stream_microphone(payload, config=None):
    config = config or {}
    api_key = config.get("api_key") or os.environ["DEEPGRAM_API_KEY"]
    url = "https://api.deepgram.com/v1/listen?encoding=linear16&sample_rate=16000&channels=1&interim_results=true&punctuate=true"
    headers = {
        "Authorization": f"Token {api_key}",
        "Content-Type": "audio/raw",
    }

    def _iter_transcripts():
        with requests.post(url, headers=headers, data=payload, stream=True, timeout=(10, None)) as resp:
            resp.raise_for_status()
            for line in resp.iter_lines(decode_unicode=True):
                if not line:
                    continue
                if line.startswith("data: "):
                    data = line[6:]
                    if data == "[DONE]":
                        break
                    try:
                        obj = requests.models.complexjson.loads(data)
                    except Exception:
                        continue
                    channel = obj.get("channel", {})
                    alternatives = channel.get("alternatives", [])
                    if alternatives:
                        transcript = alternatives[0].get("transcript")
                        if transcript:
                            yield transcript

    result = _iter_transcripts()
    return result
